        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Charles H. Bennett",
        "Gilles Brassard",
        "Artur Ekert"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum cryptography established that quantum principles can provide operationally meaningful security and helped define quantum information as a physical field.",
        "attribution": "Bennett and Brassard introduced the influential protocol; Ekert independently connected key distribution to entanglement and Bell inequalities.",
        "maturity": "The concepts have been thoroughly tested and developed into practical systems, though deployment conditions and security assumptions remain important.",
        "uncertainties": [
          "It is not self-evident whether the prize should recognize the foundational protocols, the broader field, or later demonstrations."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how fragile quantum states can, in principle, support scalable computation and reshaped the physical understanding of quantum information.",
        "attribution": "Shor and Steane introduced early quantum error-correcting codes; Kitaev's topological approach connected protection to robust code structure and inspired surface codes.",
        "maturity": "The theory is established and logical error suppression has been demonstrated, although large-scale fault-tolerant operation remains unrealized.",
        "uncertainties": [
          "These were distinct advances over several years, and the field's ultimate practical reach is not yet known."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Tilman Esslinger"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices enabled controlled studies of lattice many-body physics, including regimes that are difficult to access in solids.",
        "attribution": "Bloch and Greiner made landmark experimental contributions to strongly correlated atom systems; Esslinger established complementary capabilities for many-body simulation.",
        "maturity": "The platform has produced reproducible results across laboratories and remains a powerful experimental tool.",
        "uncertainties": [
          "The contribution overlaps with broader controlled-atom quantum simulation, and a prize would need to identify a sufficiently specific discovery."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B034",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping and opened a regime in which atomic clocks probe fundamental physics with exceptional sensitivity.",
        "attribution": "Katori introduced the lattice clock concept and magic wavelength; Ye made major experimental advances in clock performance and precision measurements.",
        "maturity": "The method is robust, independently implemented, and has enabled increasingly precise comparisons and tests.",
        "uncertainties": [
          "The field continues to advance quickly, so the most definitive scientific consequences may still be emerging."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Daniel Loss",
        "David P. DiVincenzo",
        "Jason Petta"
      ],
      "assessment": {
        "nobel_worthiness": "Semiconductor spin qubits connect quantum information to scalable solid-state devices and have enabled increasingly precise control of individual spins.",
        "attribution": "Loss and DiVincenzo articulated the influential spin-qubit proposal and criteria; Petta demonstrated key control and coherence results in quantum dots.",
        "maturity": "Several platforms now show high-fidelity operations, but scaling, uniformity, and error correction remain active challenges.",
        "uncertainties": [
          "The field is still developing, and credit for the experimental platform is distributed across many groups."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Fedor Jelezko",
        "Jörg Wrachtrup",
        "Mikhail Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Single nitrogen-vacancy spins in diamond made room-temperature quantum control and nanoscale sensing accessible, with substantial impact on quantum science.",
        "attribution": "Jelezko and Wrachtrup established key experimental control of individual defects; Lukin advanced the sensing and quantum-information framework.",
        "maturity": "Single-spin control and sensing are well demonstrated, though the breadth of applications and comparative advantage continue to be assessed.",
        "uncertainties": [
          "The discovery is a sequence of related advances rather than one sharply bounded result."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B038",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mikhail Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Rydberg blockade and neutral-atom arrays provide a programmable route to strongly interacting quantum systems and large-scale quantum control.",
        "attribution": "Browaeys led landmark experiments demonstrating programmable interacting arrays; Lukin contributed foundational ideas and influential experimental work.",
        "maturity": "The platform has advanced rapidly and shown striking capabilities, but its long-term scientific and computational reach is still being established.",
        "uncertainties": [
          "The work is recent, and attribution across theoretical proposals and multiple experimental groups remains unsettled."
        ]
      }
    }
  ]
